WITH filtered_accounts AS (SELECT * FROM accounts WHERE balance BETWEEN 28000 AND 63000 OR status <> 'FROZEN'), Summary AS (SELECT CASE WHEN status IN ('FROZEN', 'CLOSED') THEN 'priority' ELSE 'other' END AS status_group, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(status))) AS status_values, SUM(balance) AS total_balance FROM filtered_accounts GROUP BY CASE WHEN status IN ('FROZEN', 'CLOSED') THEN 'priority' ELSE 'other' END) SELECT status_group, status_values, total_balance FROM Summary WHERE total_balance >= 206000 ORDER BY status_values;
